#include "toneAC2/toneAC2.h"
#include "pin_definitions.h"
#include "settings.h"
#include "tuner.h"

/**
 * The CW keyer uses independent dot and dash inputs.
 * The sidetone is generated by the Arduino and injected into the volume control.
 */

/**
 * Starts transmitting the carrier with the sidetone
 * It assumes that we have called cwTxStart and not called cwTxStop
 * each time it is called, the cwTimeOut is pushed further into the future
 */
void cwKeydown(){
  toneAC2(PIN_CW_TONE, globalSettings.cwSideToneFreq);
  digitalWrite(PIN_CW_KEY, 1);

  globalSettings.cwExpirationTimeMs = millis() + globalSettings.cwActiveTimeoutMs;
}

/**
 * Stops the cw carrier transmission along with the sidetone
 * Pushes the cwTimeout further into the future
 */
void cwKeyUp(){
  noToneAC2();
  digitalWrite(PIN_CW_KEY, 0);
  
  globalSettings.cwExpirationTimeMs = millis() + globalSettings.cwActiveTimeoutMs;
}

//Variables for Ron's new logic
#define DIT_L 0x01 // DIT latch
#define DAH_L 0x02 // DAH latch
#define DIT_PROC 0x04 // DIT is being processed
#define PDLSWAP 0x08 // 0 for normal, 1 for swap
#define IAMBICB 0x10 // 0 for Iambic A, 1 for Iambic B
enum KSTYPE {IDLE, CHK_DIT, CHK_DAH, KEYED_PREP, KEYED, INTER_ELEMENT };
static unsigned long ktimer;
unsigned char keyerState = IDLE;
uint8_t keyerControl = 0;

static bool cwPracticeActive = false;
static uint8_t cwPracticeSegment = 0;
static bool cwPracticeToneOn = false;
static unsigned int cwPracticeFrequency = 0;
static uint16_t cwPracticeDitDurationMs = 0;
static unsigned long cwPracticeNextChangeMs = 0;

void startCwPractice(const uint16_t frequency, const uint16_t ditDurationMs)
{
  if (cwPracticeActive) {
    cwPracticeFrequency = frequency;
    cwPracticeDitDurationMs = ditDurationMs;
    if (cwPracticeToneOn) {
      toneAC2(PIN_CW_TONE, cwPracticeFrequency);
    }
    return;
  }

  cwPracticeFrequency = frequency;
  cwPracticeDitDurationMs = ditDurationMs;
  cwPracticeSegment = 0;
  cwPracticeActive = true;
  cwPracticeToneOn = true;
  toneAC2(PIN_CW_TONE, cwPracticeFrequency);
  cwPracticeNextChangeMs = millis() + cwPracticeDitDurationMs;
}

void stopCwPractice()
{
  if (cwPracticeActive) {
    noToneAC2();
    cwPracticeActive = false;
    cwPracticeToneOn = false;
  }
}

void updateCwPractice()
{
  const unsigned long now = millis();
  if (!cwPracticeActive
      || static_cast<long>(now - cwPracticeNextChangeMs) < 0) {
    return;
  }

  cwPracticeSegment = (cwPracticeSegment + 1) % 8;
  cwPracticeToneOn = cwPracticeSegment % 2 == 0;
  if (cwPracticeToneOn) {
    toneAC2(PIN_CW_TONE, cwPracticeFrequency);
  } else {
    noToneAC2();
  }

  const bool characterGap = cwPracticeSegment == 7;
  const bool dah = cwPracticeToneOn && cwPracticeSegment == 6;
  const unsigned long durationMultiplier = characterGap || dah ? 3 : 1;
  cwPracticeNextChangeMs = now + durationMultiplier * cwPracticeDitDurationMs;
}

struct DebouncedInput {
  int rawState;
  int stableState;
  unsigned long changedAt;
};

static const unsigned long PADDLE_DEBOUNCE_MS = 5;

bool readPaddlePressed(const uint32_t pin, DebouncedInput* const input) {
  const int rawState = digitalRead(pin);
  const unsigned long now = millis();
  if (rawState != input->rawState) {
    input->rawState = rawState;
    input->changedAt = now;
  } else if (input->stableState != input->rawState
             && now - input->changedAt >= PADDLE_DEBOUNCE_MS) {
    input->stableState = input->rawState;
  }
  return input->stableState == LOW;
}

uint8_t update_PaddleLatch(bool isUpdateKeyState) {
  static DebouncedInput ditInput = {HIGH, HIGH, 0};
  static DebouncedInput dahInput = {HIGH, HIGH, 0};
  uint8_t tmpKeyerControl = 0;

  if (readPaddlePressed(PIN_KEYER_DIT, &ditInput))
    tmpKeyerControl |= DIT_L;
  if (readPaddlePressed(PIN_KEYER_DAH, &dahInput))
    tmpKeyerControl |= DAH_L;

  if (isUpdateKeyState)
    keyerControl |= tmpKeyerControl;

  return tmpKeyerControl;
}

/*****************************************************************************
// New logic, by RON
// modified by KD8CEC
******************************************************************************/
void cwKeyer(void){
  bool continue_loop = true;
  uint8_t tmpKeyControl = 0;
  
  if((KeyerMode_e::KEYER_STRAIGHT == globalSettings.keyerMode)
    || (digitalRead(PIN_PTT) == 0)){//use the PTT as the key for tune up, quick QSOs
    while(1){
      tmpKeyControl = (update_PaddleLatch(false) & DIT_L)
                    | (digitalRead(PIN_PTT) ? 0 : DIT_L);
      if ((tmpKeyControl & DIT_L) == DIT_L) {
        // Straight-key mode uses DIT; PTT is also accepted as a CW key.
        if (!globalSettings.txActive){
          startTx(TuningMode_e::TUNE_CW);
          globalSettings.cwExpirationTimeMs = millis() + globalSettings.cwActiveTimeoutMs;
        }
        cwKeydown();
        
        while ((tmpKeyControl & DIT_L) == DIT_L){
          tmpKeyControl = (update_PaddleLatch(false) & DIT_L)
                        | (digitalRead(PIN_PTT) ? 0 : DIT_L);
        }
          
        cwKeyUp();
      }
      else{
        if (0 < globalSettings.cwExpirationTimeMs && globalSettings.cwExpirationTimeMs < millis()){
          globalSettings.cwExpirationTimeMs = 0;
          stopTx();
        }
        return;//Tx stop control by Main Loop
      }

    } //end of while
    
  }
  else{//KEYER_IAMBIC_*
    while(continue_loop){
      switch(keyerState){
        case IDLE:
          tmpKeyControl = update_PaddleLatch(false);
          if((tmpKeyControl == DAH_L)//Currently dah
           ||(tmpKeyControl == DIT_L)//Currently dit
           ||(tmpKeyControl == (DAH_L | DIT_L))//Currently both
           ||( keyerControl  & (DAH_L | DIT_L))){//Resolving either
             update_PaddleLatch(true);
             keyerState = CHK_DIT;
          }
          else{
            if (0 < globalSettings.cwExpirationTimeMs && globalSettings.cwExpirationTimeMs < millis()){
              globalSettings.cwExpirationTimeMs = 0;
              stopTx();
            }
            continue_loop = false;
          }
          break;
    
        case CHK_DIT:
          if (keyerControl & DIT_L) {
            keyerControl |= DIT_PROC;
            ktimer = globalSettings.cwDitDurationMs;
            keyerState = KEYED_PREP;
          }else{
            keyerState = CHK_DAH;
          }
          break;
    
        case CHK_DAH:
          if (keyerControl & DAH_L) {
            ktimer = 3*globalSettings.cwDitDurationMs;
            keyerState = KEYED_PREP;
          }else{
            keyerState = IDLE;
          }
          break;
    
        case KEYED_PREP:
          //modified KD8CEC
          if (!globalSettings.txActive){
            globalSettings.cwExpirationTimeMs = millis() + globalSettings.cwActiveTimeoutMs;
            startTx(TuningMode_e::TUNE_CW);
          }
          ktimer += millis(); // set ktimer to interval end time
          keyerControl &= ~(DIT_L + DAH_L); // clear both paddle latch bits
          keyerState = KEYED; // next state
          
          cwKeydown();
          break;
    
        case KEYED:
          if (millis() > ktimer) { // are we at end of key down ?
            cwKeyUp();
            ktimer = millis() + globalSettings.cwDitDurationMs; // inter-element time
            keyerState = INTER_ELEMENT; // next state
          }
          else if(KeyerMode_e::KEYER_IAMBIC_B == globalSettings.keyerMode){
            update_PaddleLatch(true); // early paddle latch in Iambic B mode
          }
          break;
    
        case INTER_ELEMENT:
          // Insert time between dits/dahs
          update_PaddleLatch(true); // latch paddle state
          if (millis() > ktimer) { // are we at end of inter-space ?
            if (keyerControl & DIT_PROC) { // was it a dit or dah ?
              keyerControl &= ~(DIT_L + DIT_PROC); // clear two bits
              keyerState = CHK_DAH; // dit done, check for dah
            }else{
              keyerControl &= ~(DAH_L); // clear dah latch
              keyerState = IDLE; // go idle
            }
          }
          break;
      }
  
    } //end of while
  }//end of KEYER_IAMBIC_*
}
